//
// Montana income tax withholding: "Montana Employer and Information Agent
// Guide with Montana Withholding Tax Tables - 2026", Montana Withholding
// Tax Formula: W = A + B x (G - C), by MW-4 filing status and payroll
// period. Montana now uses the federal standard deduction for the filing
// status (HB 337, 2026 rates: 4.7% / 5.65%). Tables generated by
// tools/state/generate_mt.py from the guide; all nine of its worked
// examples are in the tests.
//
// Rounding: the guide says amounts "must be rounded up to the nearest
// dollar", but all nine examples round to the NEAREST dollar ($17.34 ->
// $17). This follows the examples; flagged.
//
// MW-4 input: { filingStatus: "single" (line 1a, or line 2: married filing
//   jointly with both spouses working) | "marriedJoint" (1b) |
//   "headOfHousehold" (1c), additionalWithholdingCents?, exempt? }.
// No MW-4 on file: the guide doesn't say; this uses the single table (the
// higher-withholding choice). Flagged.
// Payroll periods: the guide has daily, weekly, biweekly, semimonthly,
// monthly and annual tables only; other frequencies throw.
//
// Wages: "net taxable pay", as for federal withholding, so pre-tax 401(k)
// is excluded.

const { formChecker, onFile, PERIOD_BY_COUNT } = require("./formUtil");
const { fromBaseTable } = require("./brackets");

// Generated by tools/state/generate_mt.py: [overCents, baseCents (A), rateBp (B)].
const FORMULA_TABLES = Object.freeze({
  single: Object.freeze({
    daily: Object.freeze([[0, 0, 0], [6200, 0, 470], [24500, 900, 565]]),
    weekly: Object.freeze([[0, 0, 0], [31000, 0, 470], [122300, 4300, 565]]),
    biweekly: Object.freeze([[0, 0, 0], [61900, 0, 470], [244600, 8600, 565]]),
    semimonthly: Object.freeze([[0, 0, 0], [67100, 0, 470], [265000, 9400, 565]]),
    monthly: Object.freeze([[0, 0, 0], [134200, 0, 470], [530000, 18700, 565]]),
    annual: Object.freeze([[0, 0, 0], [1610000, 0, 470], [6360000, 223300, 565]]),
  }),
  marriedJoint: Object.freeze({
    daily: Object.freeze([[0, 0, 0], [12400, 0, 470], [48900, 1800, 565]]),
    weekly: Object.freeze([[0, 0, 0], [61900, 0, 470], [244600, 8600, 565]]),
    biweekly: Object.freeze([[0, 0, 0], [123800, 0, 470], [489200, 17200, 565]]),
    semimonthly: Object.freeze([[0, 0, 0], [134200, 0, 470], [530000, 18700, 565]]),
    monthly: Object.freeze([[0, 0, 0], [268300, 0, 470], [1060000, 37200, 565]]),
    annual: Object.freeze([[0, 0, 0], [3220000, 0, 470], [12720000, 446500, 565]]),
  }),
  headOfHousehold: Object.freeze({
    daily: Object.freeze([[0, 0, 0], [9300, 0, 470], [36700, 1300, 565]]),
    weekly: Object.freeze([[0, 0, 0], [46400, 0, 470], [183500, 6500, 565]]),
    biweekly: Object.freeze([[0, 0, 0], [92900, 0, 470], [366900, 12900, 565]]),
    semimonthly: Object.freeze([[0, 0, 0], [100600, 0, 470], [397500, 14000, 565]]),
    monthly: Object.freeze([[0, 0, 0], [201300, 0, 470], [795000, 28000, 565]]),
    annual: Object.freeze([[0, 0, 0], [2415000, 0, 470], [9540000, 334900, 565]]),
  }),
});

const TABLES = Object.freeze({
  2026: Object.freeze({
    formulaTables: FORMULA_TABLES,
    sources: Object.freeze([
      "Montana DOR, Montana Employer and Information Agent Guide with Montana Withholding Tax Tables (2026): https://revenuefiles.mt.gov/files/Forms/Montana_Employer_and_Information_Agent_Guide_with_Tax_Tables.pdf",
      "Montana DOR, Updated Montana Wage Withholding Tables and MW-4 (2026): https://revenue.mt.gov/news/recent-news/2026-withholding-updates",
    ]),
  }),
});

function validateForm(form) {
  if (!onFile(form)) return;
  const c = formChecker("Montana MW-4");
  c.bool(form, "exempt");
  if (form.exempt) return;
  c.oneOf(form, "filingStatus", ["single", "marriedJoint", "headOfHousehold"]);
  c.cents(form, "additionalWithholdingCents");
}

function compute({ taxYear, wagesCents, payPeriodsPerYear, form }) {
  const t = TABLES[taxYear];
  validateForm(form);
  const has = onFile(form);
  if (has && form.exempt) return { stateCents: 0, formBasis: "mw-4-exempt", lines: {} };
  const status = has ? form.filingStatus : "single";
  const period = PERIOD_BY_COUNT[payPeriodsPerYear];
  const rows = period && t.formulaTables[status][period];
  if (!rows) throw new Error(`Montana has no withholding table for ${payPeriodsPerYear} pay periods a year`);
  const W = fromBaseTable(wagesCents, rows);
  const extra = has ? form.additionalWithholdingCents ?? 0 : 0;
  return {
    stateCents: Math.round(W / 100) * 100 + extra,
    formBasis: has ? "mw-4" : "none-on-file-single",
    lines: { period, status, unroundedCents: W },
  };
}

module.exports = {
  code: "MT",
  name: "Montana",
  wageBasis: "federal-income-tax-wages",
  years: Object.keys(TABLES).map(Number),
  TABLES,
  validateForm,
  compute,
};
